/**
 * 측정 도중 질문 삭제·수정 차단 (2026-10-13).
 *
 * 🔴 사고 경로: 측정 결과 저장(`persistAuditTracking`)은 질문을 텍스트로 upsert 한다. 측정 중에 고객이 질문을
 *   지우거나 고치면 저장 단계가 그 질문을 `isAutoGenerated: true` 로 **다시 만들어 되살린다**.
 *   → 진행 중(또는 결과 저장 마무리 전)에는 삭제·수정을 서버에서 막는다.
 *
 * @vitest-environment node
 */
import { beforeEach, describe, expect, it, vi } from "vitest";

const h = vi.hoisted(() => ({
  auditJobFindFirst: vi.fn(),
  promptFindUnique: vi.fn(),
  promptDelete: vi.fn(),
  promptUpdate: vi.fn(),
  trackingCount: vi.fn(),
}));

vi.mock("@repo/database", () => ({
  database: {
    auditJob: { findFirst: h.auditJobFindFirst },
    prompt: {
      findUnique: h.promptFindUnique,
      delete: h.promptDelete,
      update: h.promptUpdate,
    },
    tracking: { count: h.trackingCount },
  },
}));
vi.mock("@/lib/db/scoped", () => ({
  requireOrg: () => Promise.resolve("org_1"),
  scopedBrandById: () => Promise.resolve({ id: "brand_1" }),
}));
vi.mock("@repo/observability/log", () => ({
  log: { info: vi.fn(), warn: vi.fn(), error: vi.fn() },
}));
vi.mock("@repo/observability/error", () => ({ parseError: String }));

import { deletePromptAction } from "../app/actions/brand/delete-prompt";
import { editPromptAction } from "../app/actions/brand/edit-prompt";
import { hasInFlightMeasurement } from "../lib/brand/measurement-in-flight";

const MSG = "측정이 진행 중이라 지금은 질문을 바꿀 수 없어요";

beforeEach(() => {
  for (const fn of Object.values(h)) {
    fn.mockReset();
  }
  h.promptFindUnique.mockResolvedValue({
    id: "p1",
    brandId: "brand_1",
    isAutoGenerated: true,
    text: "기존 질문",
  });
  h.trackingCount.mockResolvedValue(0);
  h.promptDelete.mockResolvedValue({});
  h.promptUpdate.mockResolvedValue({});
});

describe("측정 진행 중에는 질문을 바꾸지 않는다", () => {
  it("진행 중이면 삭제를 거부하고 DB 를 건드리지 않는다", async () => {
    h.auditJobFindFirst.mockResolvedValue({ id: "job_1" });
    const result = await deletePromptAction({ promptId: "p1" });
    expect("error" in result && result.error).toContain(MSG);
    expect(h.promptDelete).not.toHaveBeenCalled();
  });

  it("진행 중이면 수정을 거부하고 DB 를 건드리지 않는다", async () => {
    h.auditJobFindFirst.mockResolvedValue({ id: "job_1" });
    // 중복 검사 단계까지 가지 않아야 하지만, 가더라도 중복 없음으로 둔다.
    h.promptFindUnique
      .mockResolvedValueOnce({
        id: "p1",
        brandId: "brand_1",
        isAutoGenerated: true,
        text: "기존 질문",
      })
      .mockResolvedValue(null);
    const result = await editPromptAction({
      promptId: "p1",
      text: "새 질문입니다",
    });
    expect("error" in result && result.error).toContain(MSG);
    expect(h.promptUpdate).not.toHaveBeenCalled();
  });

  it("진행 중이 아니면 기존처럼 삭제·수정된다", async () => {
    h.auditJobFindFirst.mockResolvedValue(null);
    expect(await deletePromptAction({ promptId: "p1" })).toMatchObject({
      ok: true,
    });
    expect(h.promptDelete).toHaveBeenCalled();

    h.promptFindUnique
      .mockResolvedValueOnce({
        id: "p1",
        brandId: "brand_1",
        isAutoGenerated: true,
        text: "기존 질문",
      })
      .mockResolvedValueOnce(null);
    expect(
      await editPromptAction({ promptId: "p1", text: "새 질문입니다" })
    ).toEqual({ ok: true });
    expect(h.promptUpdate).toHaveBeenCalled();
  });
});

describe("hasInFlightMeasurement — 무엇을 '진행 중'으로 보나", () => {
  const now = new Date("2026-10-13T12:00:00.000Z");

  it("최근 30분 안의 queued/processing, 또는 Tracking 저장 단계가 미완인 완료 회차를 본다", async () => {
    h.auditJobFindFirst.mockResolvedValue(null);
    await hasInFlightMeasurement("brand_1", now);
    const where = h.auditJobFindFirst.mock.calls[0]?.[0].where;
    expect(where.brandId).toBe("brand_1");
    // 30분 창 — 죽은 작업이 편집을 영구히 막지 않는다.
    expect(where.createdAt.gte).toEqual(new Date("2026-10-13T11:30:00.000Z"));
    expect(where.OR[0]).toEqual({ status: { in: ["queued", "processing"] } });
    const stages = where.OR[1].OR.map(
      (c: { postprocessing: { equals: string } }) => c.postprocessing.equals
    );
    expect(stages.sort()).toEqual(
      ["failed", "pending", "reconciling", "unknown"].sort()
    );
  });

  it("회차가 있으면 true, 없으면 false", async () => {
    h.auditJobFindFirst.mockResolvedValueOnce({ id: "j" });
    expect(await hasInFlightMeasurement("b", now)).toBe(true);
    h.auditJobFindFirst.mockResolvedValueOnce(null);
    expect(await hasInFlightMeasurement("b", now)).toBe(false);
  });
});
